	-- 006c5c40 (_CIpow, encrypted): ST1=x, ST0=y -> x^y
	local y = F[FT]; F[FT] = nil; FT = FT - 1
	local x = F[FT]
	F[FT] = (x == 0) and 0 or x ^ y
	ESP = band(ESP + 4)
